'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let file=null, result=null, pollId=null, busy=false, pdfBlob=null;
let tpl=null, tplSpec='';
let settings={agentUrl:'',agentToken:'',llmUrl:'',llmModel:'',llmKey:'',vlUrl:'',vlModel:'',vlKey:''};
try{const saved=JSON.parse(localStorage.getItem('mopai.settings')||'{}');for(const k of ['agentUrl','llmUrl','llmModel','vlUrl','vlModel'])settings[k]=saved[k]||'';}catch{}
let history=[];try{history=JSON.parse(localStorage.getItem('mopai.history')||'[]');}catch{}
const steps=['解析文档与资源','组织 LaTeX 工程','编译并有限修复','结构检查与内容待复核项','打包下载文件'];
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function escapeHTML(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function view(name){$$('.view').forEach(e=>e.classList.add('hidden'));$('#'+name+'View').classList.remove('hidden');$$('.nav[data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===name));$('#pageTitle').textContent={workspace:'排版工作台',templates:'模板库',assistant:'LaTeX 助手',history:'最近任务'}[name];if(name==='history')renderHistory();window.scrollTo({top:0,behavior:'smooth'});}
$$('.nav[data-view]').forEach(e=>e.onclick=()=>view(e.dataset.view));$('.brand').onclick=e=>{e.preventDefault();view('workspace');};
function updateMode(){const ready=Boolean(settings.agentUrl&&settings.agentToken);$('#modePill').innerHTML='<i></i> '+(ready?'Agent 已配置':'示例模式');$('#chatMode').textContent=ready?'已连接模型配置':'示例问答';$('#startNote').textContent=ready?'将通过你的 Agent 调用模型与编译服务':'上传文件后，连接 Agent 开始真实处理';}
function openSettings(){for(const [k,v]of Object.entries(settings))$('#'+k).value=v;$('#connectionStatus').textContent='';$('#settingsDialog').showModal();}
['openSettings','headerSettings'].forEach(id=>$('#'+id).onclick=openSettings);
$$('.close-dialog').forEach(e=>e.onclick=()=>e.closest('dialog').close());
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
['guideBtn','footerGuide'].forEach(id=>$('#'+id).onclick=()=>$('#guideDialog').showModal());
function readSettings(){const s={};for(const k of Object.keys(settings))s[k]=$('#'+k).value.trim();s.agentUrl=s.agentUrl.replace(/\/$/,'');return s;}
$('#settingsForm').onsubmit=e=>{e.preventDefault();const s=readSettings();if(s.agentUrl&&new URL(s.agentUrl).protocol==='http:'&&location.protocol==='https:'&&!/^http:\/\/(localhost|127\.0\.0\.1)(:|\/|$)/.test(s.agentUrl)){toast('HTTPS 页面请连接 HTTPS Agent，或在本地打开工作台');return;}settings=s;const safe={};for(const k of ['agentUrl','llmUrl','llmModel','vlUrl','vlModel'])safe[k]=s[k];try{localStorage.setItem('mopai.settings',JSON.stringify(safe));}catch{}updateMode();$('#settingsDialog').close();toast('配置已保存；密钥仅保留在本页内存');};
function model(kind,s=settings){return {base_url:s[kind+'Url'],model:s[kind+'Model'],api_key:s[kind+'Key']};}
async function api(path,options={},s=settings){if(!s.agentUrl)throw Error('请先填写 Agent 服务地址');const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),options.timeout||200000);try{const r=await fetch(s.agentUrl+path,{...options,signal:controller.signal,headers:{'X-Agent-Token':s.agentToken,...options.headers}});if(!r.ok){let msg='Agent 返回 HTTP '+r.status;try{const body=await r.json();if(typeof body.detail==='string')msg=body.detail;}catch{}throw Error(msg);}return r;}catch(e){if(e.name==='AbortError')throw Error('请求超时，请检查 Agent 或模型连接');if(e instanceof TypeError)throw Error('无法连接 Agent，请检查地址、HTTPS 和 ALLOWED_ORIGINS 配置');throw e;}finally{clearTimeout(timer);}}
$('#testConnection').onclick=async()=>{const btn=$('#testConnection'),s=readSettings();btn.disabled=true;$('#connectionStatus').textContent='正在检查 Agent 与已填写的模型…';try{const health=await(await api('/health',{timeout:15000},s)).json();let tested=0;for(const k of ['llm','vl']){if(s[k+'Model']){await api('/test-model',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(model(k,s))},s);tested++;}}$('#connectionStatus').textContent='✓ Agent 可连接；'+(tested?tested+' 个模型连接通过':'尚未填写模型，未测试模型')+'；'+(health.compiler_configured?'编译服务地址已配置（本次未编译）':'尚未配置编译服务');}catch(e){$('#connectionStatus').textContent=e.message;}finally{btn.disabled=false;}};
function setFile(f){if(!f)return;if(busy){toast('当前任务尚未结束，请稍后上传');return;}const ext=f.name.split('.').pop().toLowerCase();if(!['docx','pdf','tex','zip','png','jpg','jpeg','webp','md','txt'].includes(ext)){toast('暂不支持此格式；旧版 DOC 请先另存为 DOCX');return;}if(f.size>60*1024*1024){toast('文件超过 60 MB，请拆分或压缩后上传');return;}file=f;$('#dropTitle').textContent=f.name;$('#dropDesc').textContent=(f.size/1024/1024).toFixed(2)+' MB · 已选中，等待提交至你的 Agent';$('#clearFile').classList.remove('hidden');}
$('#fileInput').onchange=e=>setFile(e.target.files[0]);$('#dropzone').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#fileInput').click();}};
$('#dropzone').addEventListener('dragover',e=>{e.preventDefault();$('#dropzone').classList.add('dragover');});$('#dropzone').addEventListener('dragleave',()=>$('#dropzone').classList.remove('dragover'));$('#dropzone').addEventListener('drop',e=>{e.preventDefault();$('#dropzone').classList.remove('dragover');if(e.dataTransfer.files.length>1){toast('请上传一个主文档；多个资源请打包为 ZIP');return;}setFile(e.dataTransfer.files[0]);});
$('#clearFile').onclick=()=>{file=null;$('#fileInput').value='';$('#dropTitle').innerHTML='将文档拖到这里，或<span>点击上传</span>';$('#dropDesc').textContent='Word、PDF、TeX 工程，也可以是一张图片';$('#clearFile').classList.add('hidden');};
async function analyzeTemplate(f){if(!settings.agentUrl||!settings.agentToken){$('#templateSpec').classList.add('hidden');return;}$('#templateSpec').classList.remove('hidden');$('#templateSpec').innerHTML='<span class="picker-hint">正在识别模板中的排版要求…</span>';try{const form=new FormData();form.append('file',f);const d=await(await api('/template/analyze',{method:'POST',body:form})).json();tplSpec=d.spec||'';$('#templateSpec').innerHTML='<div class="spec-head">已识别排版要求</div><pre>'+escapeHTML(d.spec)+'</pre>'+((d.warnings||[]).length?'<ul class="spec-warn">'+d.warnings.map(w=>'<li>'+escapeHTML(w)+'</li>').join('')+'</ul>':'');}catch(e){tplSpec='';$('#templateSpec').innerHTML='<span class="picker-hint">'+escapeHTML(e.message)+'</span>';}}
function setTemplate(f){if(!f)return;const ext=f.name.split('.').pop().toLowerCase();if(!['tex','zip'].includes(ext)){toast('模板仅支持 .tex，或把模板工程打包为 .zip');return;}if(f.size>60*1024*1024){toast('模板文件超过 60 MB');return;}tpl=f;$('#templateHint').textContent=f.name;$('#templateClear').classList.remove('hidden');analyzeTemplate(f);}
$('#templatePick').onclick=()=>$('#templateFile').click();
$('#templateFile').onchange=e=>setTemplate(e.target.files[0]);
$('#templateClear').onclick=()=>{tpl=null;tplSpec='';$('#templateFile').value='';$('#templateHint').textContent='未选择 · 不传则用上方内置模板';$('#templateClear').classList.add('hidden');$('#templateSpec').classList.add('hidden');};
function taskPane(pane){['inputArea','progressArea','resultArea'].forEach(id=>$('#'+id).classList.toggle('hidden',id!==pane));}
function drawProgress(job){$('#progressName').textContent=job.name;$('#progressMessage').textContent=job.message;$('#progressBar').style.width=(job.status==='completed'?100:Math.max(5,(job.step+1)*19))+'%';$('#progressSteps').innerHTML=steps.map((s,i)=>'<li class="'+(i<=job.step?'done':'')+'">'+escapeHTML(s)+(i<job.step?' ✓':'')+'</li>').join('');}
function addHistory(item){history=history.filter(h=>h.id!==item.id);history.unshift(item);history=history.slice(0,20);try{localStorage.setItem('mopai.history',JSON.stringify(history));}catch{}}
$('#startBtn').onclick=async()=>{if(!file){toast('请先上传文档，也可以点击“体验示例”');return;}if(busy)return;if(!settings.agentUrl||!settings.agentToken){toast('先连接你部署的 Agent，即可处理这份文档');openSettings();return;}const ext=file.name.split('.').pop().toLowerCase();if(['pdf','png','jpg','jpeg','webp'].includes(ext)&&(!settings.vlModel||!settings.vlUrl)){toast('PDF 和图片识别需要配置 VL 模型');openSettings();return;}if($('#instructions').value.trim()&&!settings.llmModel){toast('额外排版要求需要配置文本模型');openSettings();return;}const config={llm:model('llm'),vl:model('vl'),template:$('#template').value,engine:$('#engine').value,entry:$('#entry').value.trim()||'main.tex',instructions:$('#instructions').value.trim(),repair_attempts:2};const form=new FormData();form.append('file',file);form.append('config',JSON.stringify(config));if(tpl)form.append('template',tpl);busy=true;taskPane('progressArea');$('#backFromProgress').classList.add('hidden');drawProgress({name:file.name,message:'正在上传文件到你的 Agent…',step:-1});try{const j=await(await api('/jobs',{method:'POST',body:form})).json();addHistory({id:j.id,name:file.name,mode:'agent',agent:settings.agentUrl,status:'running',time:Date.now()});await pollJob(j.id);}catch(e){busy=false;$('#progressMessage').textContent=e.message;$('#backFromProgress').classList.remove('hidden');toast(e.message);}};
async function pollJob(id){clearTimeout(pollId);try{const job=await(await api('/jobs/'+id,{timeout:20000})).json();drawProgress(job);if(job.status==='completed'){busy=false;const item=history.find(h=>h.id===id);if(item){item.status='completed';addHistory(item);}result={...job,mode:'agent',agent:settings.agentUrl};await showResult();return;}if(job.status==='failed'){busy=false;const item=history.find(h=>h.id===id);if(item){item.status='failed';addHistory(item);}$('#backFromProgress').classList.remove('hidden');toast(job.message);return;}pollId=setTimeout(()=>pollJob(id),1800);}catch(e){busy=false;$('#progressMessage').textContent=e.message+'。任务可能仍在服务器执行，可从最近任务重新打开。';$('#backFromProgress').classList.remove('hidden');}}
$('#backFromProgress').onclick=()=>taskPane('inputArea');$('#newTask').onclick=()=>{taskPane('inputArea');view('workspace');};
async function sample(){if(busy){toast('请等待当前任务结束');return;}view('workspace');try{const [tex,report,log]=await Promise.all(['sample/main.tex','sample/report.json','sample/compile.log'].map(async p=>{const r=await fetch(p);if(!r.ok)throw Error('示例文件加载失败');return p.endsWith('json')?r.json():r.text();}));result={mode:'sample',id:'sample',name:'注意力机制：从序列建模到文档理解',source:tex,report,log,files:['source','pdf','zip','report','log']};addHistory({id:'sample',name:result.name,mode:'sample',status:'completed',time:Date.now()});await showResult();toast('已打开真实编译的示例；未处理你上传的文件');}catch(e){toast(e.message);}}
['sampleBtn','sideSample'].forEach(id=>$('#'+id).onclick=sample);
function setTab(tab){$$('[data-tab]').forEach(e=>e.classList.toggle('active',e.dataset.tab===tab));['pdf','source','report','log'].forEach(t=>$('#'+t+'Pane').classList.toggle('hidden',t!==tab));}
$$('[data-tab]').forEach(e=>e.onclick=()=>setTab(e.dataset.tab));
async function showResult(){taskPane('resultArea');$('#resultName').textContent=result.name;$('#resultDesc').textContent=result.mode==='sample'?'示例工程 · 使用真实 XeLaTeX 编译产物展示交付效果':'任务处理结束 · 请分别查看编译状态与内容待复核项';const report=result.report;const ok=report.compile_status==='passed';$('#compileBadge').textContent=ok?'✓ 编译通过':report.compile_status==='not_run'?'编译未执行':'编译未通过';$('#compileBadge').className='tag '+(ok?'':report.compile_status==='not_run'?'warning':'error');$('#resultMeta').textContent=(report.engine||'xelatex')+' · '+report.attempts+' 次编译 · '+(result.mode==='sample'?'示例交付':'真实任务');$('#sourcePane').textContent=result.source;$('#logPane').textContent=result.log||'打开此标签后加载完整日志。';const labels={figures:'图片引用',display_math:'行间公式组',citations:'文献引用命令',sections:'章节标题'};$('#reportPane').innerHTML='<h3>内容状态：待复核</h3><p>'+escapeHTML(report.content_note||'')+'</p>'+(report.template_applied?'<h3>已套用你上传的模板</h3><pre class="template-applied">'+escapeHTML(report.template_spec||'')+'</pre>':'')+'<table><thead><tr><th>结构指标</th><th>处理前</th><th>处理后</th></tr></thead><tbody>'+Object.keys(labels).map(k=>'<tr><td>'+labels[k]+'</td><td>'+(report.before?.[k]??'—')+'</td><td>'+(report.after?.[k]??'—')+'</td></tr>').join('')+'</tbody></table><h3>核验说明与待复核项</h3><ul>'+(report.warnings||[]).map(w=>'<li>'+escapeHTML(w)+'</li>').join('')+'</ul>';
$$('[data-download]').forEach(e=>e.disabled=!result.files.includes(e.dataset.download));$('#noPdf').classList.toggle('hidden',result.files.includes('pdf'));$('#pdfFrame').classList.toggle('hidden',!result.files.includes('pdf'));if(pdfBlob){URL.revokeObjectURL(pdfBlob);pdfBlob=null;}$('#pdfFrame').removeAttribute('src');if(result.files.includes('pdf')){if(result.mode==='sample')$('#pdfFrame').src='sample/output.pdf#toolbar=0&navpanes=0';else try{const b=await(await api('/jobs/'+result.id+'/download/pdf')).blob();pdfBlob=URL.createObjectURL(b);$('#pdfFrame').src=pdfBlob+'#toolbar=0';}catch(e){toast(e.message);}}setTab(result.files.includes('pdf')?'pdf':'source');}
$('[data-tab="log"]').addEventListener('click',async()=>{if(result?.mode==='agent')try{$('#logPane').textContent=await(await api('/jobs/'+result.id+'/download/log')).text();}catch(e){$('#logPane').textContent=e.message;}});
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
$$('[data-download]').forEach(e=>e.onclick=async()=>{if(!result)return;const kind=e.dataset.download,names={source:'main.tex',pdf:'output.pdf',zip:'latex-project.zip',report:'report.json',log:'compile.log'};try{if(result.mode==='sample'){const url='sample/'+(kind==='zip'?'latex-project.zip':names[kind]);const r=await fetch(url);if(!r.ok)throw Error('下载文件不存在');downloadBlob(await r.blob(),names[kind]);}else downloadBlob(await(await api('/jobs/'+result.id+'/download/'+kind)).blob(),names[kind]);}catch(err){toast(err.message);}});
$('#copySource').onclick=async()=>{try{await navigator.clipboard.writeText(result.source);toast('源码已复制');}catch{toast('复制不可用，请下载源码文件');}};
$('#askAboutResult').onclick=()=>{view('assistant');$('#chatContext').value=result.source;$('#question').focus();};
const templates=[['ctexart','中文学术论文','适合中文研究论文、课程报告与技术文档。','学术论文标题','中文摘要 · 关键词'],['article','英文标准论文','简洁的单栏结构，适合英文初稿与研究笔记。','A Research Paper','Abstract · Keywords'],['twocolumn','英文双栏论文','紧凑的双栏布局，适合会议稿与技术交流。','A Two-column Paper','Abstract · Keywords']];
$('#templateGallery').innerHTML=templates.map(([id,title,desc,paper,sub])=>'<article class="card template-item"><div class="template-preview"><div class="large-paper '+(id==='twocolumn'?'two':'')+'"><strong>'+paper+'</strong><small>Author · Institution</small><small>'+sub+'</small><div class="lines"></div></div></div><h3>'+title+'</h3><p>'+desc+'</p><button class="outline-button" data-template="'+id+'">使用这个模板 ↗</button></article>').join('');
$$('[data-template]').forEach(b=>b.onclick=()=>{$('#template').value=b.dataset.template;view('workspace');taskPane('inputArea');toast('已选择'+templates.find(t=>t[0]===b.dataset.template)[1]);});
function renderHistory(){if(!history.length){$('#historyList').innerHTML='<div class="empty-state">还没有任务<p>从上传第一份文档，或体验示例开始。</p><button class="outline-button" id="historySample">体验示例 ↗</button></div>';$('#historySample').onclick=sample;return;}$('#historyList').innerHTML=history.map((h,i)=>'<div class="history-row"><span>▤</span><div><strong>'+escapeHTML(h.name)+'</strong><small>'+(h.mode==='sample'?'示例工程':'真实任务')+' · '+new Date(h.time).toLocaleString('zh-CN')+' · '+({completed:'已完成',running:'处理中',failed:'处理失败'}[h.status]||h.status)+'</small></div><button class="outline-button" data-history="'+i+'">打开 ↗</button></div>').join('');$$('[data-history]').forEach(b=>b.onclick=async()=>{const h=history[+b.dataset.history];if(h.mode==='sample'){sample();return;}if(settings.agentUrl!==h.agent){toast('请先在设置中连接此任务原来的 Agent');openSettings();return;}view('workspace');busy=true;taskPane('progressArea');await pollJob(h.id);});}
const preset={
'中文显示不出来怎么办？':'将编译引擎切换为 XeLaTeX，并使用 ctex 文档类：\n\n```latex\n\\documentclass[UTF8]{ctexart}\n\\begin{document}\n你好，LaTeX！\n\\end{document}\n```\n\n若仍提示缺字，确认环境已安装 CTeX 与中文字体。此为预设示例，未对你的文件执行编译。',
'Undefined control sequence 怎么修复？':'先看日志中第一个 `Undefined control sequence` 后面的命令。检查拼写，并加载定义该命令的宏包。\n\n例如 `\\includegraphics` 未定义，在导言区加入：\n\n```latex\n\\usepackage{graphicx}\n```\n\n如果是你自定义的命令，请补上定义。此为预设示例；具体问题可粘贴首个报错与相关源码。',
'图片怎么固定在当前位置？':'加载 float 宏包，将图片位置参数改为 `[H]`：\n\n```latex\n\\usepackage{graphicx}\n\\usepackage{float}\n\n% 正文中\n\\begin{figure}[H]\n  \\centering\n  \\includegraphics[width=0.8\\linewidth]{figures/example.png}\n  \\caption{图片说明}\n  \\label{fig:example}\n\\end{figure}\n```\n\n将图片路径替换为真实文件。强制固定可能留下页内空白，常规论文可优先尝试 `[htbp]`。此为预设示例，未运行编译。'};
function message(text,kind,label){const div=document.createElement('div');div.className='message '+kind;const small=document.createElement('small');small.textContent=label;div.append(small);const parts=text.split(/(```[\s\S]*?```)/g);for(const part of parts){if(part.startsWith('```')){const pre=document.createElement('pre');pre.textContent=part.replace(/^```[^\n]*\n?/,'').replace(/```$/,'');div.append(pre);}else div.append(document.createTextNode(part));}$('#messages').append(div);$('#messages').scrollTop=$('#messages').scrollHeight;return div;}
$('#chatForm').onsubmit=async e=>{e.preventDefault();const question=$('#question').value.trim();if(!question)return;const connected=settings.agentUrl&&settings.agentToken&&settings.llmModel&&settings.llmUrl;if(!connected&&!preset[question]){toast('自由问答需要连接 Agent 和文本模型；也可体验下方预设问题');openSettings();return;}$('.welcome-message')?.remove();message(question,'user','你');$('#question').value='';$('#sendQuestion').disabled=true;const pending=message('正在获取解决方案…','answer','LaTeX 助手');try{const text=connected?(await(await api('/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:model('llm'),question,context:$('#chatContext').value})})).json()).answer:preset[question];pending.remove();message(text,'answer',connected?'LaTeX 助手':'预设示例 · LaTeX 助手');}catch(err){pending.textContent=err.message;}finally{$('#sendQuestion').disabled=false;}};
$$('[data-question]').forEach(b=>b.onclick=()=>{$('#question').value=b.dataset.question;$('#chatForm').requestSubmit();});updateMode();
